  // Rotate an image blob by a right angle (CW degrees) on a canvas and re-encode.
  // Anything that isn't JPEG re-encodes losslessly as PNG; JPEG is recompressed at
  // high quality — a truly lossless right-angle JPEG rotation would need a block-level
  // transform, out of scope here. Returns { blob, type, swap } (swap = dims transposed).
  async function rotateImageBlob(blob, deg) {
    const rot = ((deg % 360) + 360) % 360;
    const bmp = await createImageBitmap(blob);
    try {
      const swap = rot === 90 || rot === 270, w = bmp.width, h = bmp.height;
      const cv = document.createElement('canvas');
      cv.width = swap ? h : w; cv.height = swap ? w : h;
      const ctx = cv.getContext('2d');
      ctx.translate(cv.width / 2, cv.height / 2);
      ctx.rotate(rot * Math.PI / 180);
      ctx.drawImage(bmp, -w / 2, -h / 2);
      const type = blob.type === 'image/jpeg' ? 'image/jpeg' : 'image/png';
      const out = await new Promise(res => cv.toBlob(res, type, type === 'image/jpeg' ? 0.95 : undefined));
      return out ? { blob: out, type: out.type || type, swap } : null;
    } finally { bmp.close && bmp.close(); }
  }
  let _rotBusy = false;
  async function rotateLbCover(deg) {
    if (_rotBusy) return;
    const it = byId(_lb); if (!it || it._pdf || it._sourcing) return;
    const ov = document.getElementById('as-lb');
    _rotBusy = true; if (ov) ov.classList.add('as-lb-rotbusy');
    asLog.info(`Rotate: ${it._new ? 'new' : 'existing #' + it.id} by ${deg}° (${it._new ? 'in place' : 'replace'})`);
    try {
      // source pixels: a staged new cover already holds its blob; an existing cover is
      // fetched full-resolution from CAA (same CORS path Download uses)
      // upgrade http→https so fetching an existing original isn't blocked as mixed content
      const srcUrl = (it._new ? it._file : (it._img || imgUrl(it.id))).replace(/^http:\/\//i, 'https://');
      const srcBlob = (it._new && it._fileObj) ? it._fileObj
        : await fetch(srcUrl).then(r => { if (!r.ok) throw new Error('fetch ' + r.status); return r.blob(); });
      const r = await rotateImageBlob(srcBlob, deg);
      if (!r) { toast('Rotate failed — the image could not be re-encoded'); return; }
      const ow = it.w, oh = it.h, ext = r.type === 'image/png' ? 'png' : 'jpg';
      if (it._new) {
        // #678 rotate the staged blob in place — nothing was ever on the release, so no replace
        try { URL.revokeObjectURL(it._file); } catch (e) {}
        const name = (it._fileObj && it._fileObj.name) || ('image.' + ext);
        it._file = URL.createObjectURL(r.blob);
        it._fileObj = new File([r.blob], name, { type: r.type });
        it.bytes = r.blob.size; it.fmt = fileFormat(r.type) || it.fmt;
        it._contentKey = await fileKey(it._fileObj);
        if (it._rotatedFrom) it._rotDeg = (((it._rotDeg || 0) + deg) % 360 + 360) % 360;   // #678 further rotations of a staged replacement keep the note's angle accurate
        if (ow && oh) { it.w = r.swap ? oh : ow; it.h = r.swap ? ow : oh; } else { it.w = 0; it.h = 0; measure(it); }
        _imgCache.delete(String(it.id));
        resetZoom(); paintLightbox();
      } else {
        // #678 existing published cover: CAA images are immutable, so stage the rotated copy
        // as a NEW cover in the same slot (keeping its types + comment) and mark the original removed
        const file = new File([r.blob], `${it.id}-rot.${ext}`, { type: r.type });
        const nu = newItem(file, { types: it.types.slice(), comment: it.comment, exactName: true });
        nu._contentKey = await fileKey(file);
        nu._rotatedFrom = it.id; nu._rotDeg = ((deg % 360) + 360) % 360;
        if (ow && oh) { nu.w = r.swap ? oh : ow; nu.h = r.swap ? ow : oh; }
        it._del = true; it._sel = false;
        const rest = MODEL.slice().sort((a, b) => a.order - b.order);
        rest.splice(rest.indexOf(it) + 1, 0, nu);
        MODEL = rest; MODEL.forEach((m, i) => m.order = i);
        if (!(ow && oh)) measure(nu);
        _lb = nu.id; _cursorId = nu.id; resetZoom(); paintLightbox();
        toast('Rotated — staged as a replacement; the original is marked for removal');
      }
      render();
    } catch (e) {
      logErr('Rotate failed', e); toast('Rotate failed — see the log');
    } finally {
      _rotBusy = false; if (ov) ov.classList.remove('as-lb-rotbusy');
    }
  }

  // ── keyboard cursor (arrows select / move; Enter opens lightbox) ──────────────
  let _cursorId = null;
  function markCursor(scroll) {
    root.querySelectorAll('.as-card.as-cursor').forEach(c => c.classList.remove('as-cursor'));
    if (!_cursorId) return;
    const c = root.querySelector(`.as-card[data-id="${CSS.escape(String(_cursorId))}"]`);
    if (c) { c.classList.add('as-cursor'); if (scroll) c.scrollIntoView({ block: 'nearest' }); }
  }
  function moveCursor(dx, dy) {
    const cards = [...root.querySelectorAll('.as-card:not(.del)')];
    if (!cards.length) return;
    let cur = cards.find(c => c.dataset.id === String(_cursorId)) || cards[0];
    if (!_cursorId) { _cursorId = cur.dataset.id; markCursor(true); return; }
    const r0 = cur.getBoundingClientRect();
    let best = null, bestD = Infinity;
    for (const c of cards) {
      if (c === cur) continue;
      const r = c.getBoundingClientRect();
      const ddx = (r.left + r.width / 2) - (r0.left + r0.width / 2);
      const ddy = (r.top + r.height / 2) - (r0.top + r0.height / 2);
      if (dx > 0 && ddx <= 4) continue; if (dx < 0 && ddx >= -4) continue;
      if (dy > 0 && ddy <= 4) continue; if (dy < 0 && ddy >= -4) continue;
      // penalise off-axis drift so motion stays mostly in the requested direction
      const d = (dx ? Math.abs(ddx) + Math.abs(ddy) * 3 : Math.abs(ddy) + Math.abs(ddx) * 3);
      if (d < bestD) { bestD = d; best = c; }
    }
    if (best) { _cursorId = best.dataset.id; markCursor(true); }
  }
  /* #554 (majkinetor: "there is a second click again" / "That '&Paste' button
     should go away"). A real paste GESTURE carries its data with no permission
     and therefore no Chrome chip — so copy a URL, press Ctrl+V anywhere on the
     gallery, and it imports. That is one keystroke and no button at all, which
     is fewer steps than the flow he was objecting to rather than more.
     Ignored while typing somewhere, and while a lightbox or a popover has the
     page, so it can never eat a paste meant for a comment box or the URL input
     (which has its own handler). */
  document.addEventListener('paste', e => {
    if (SETTINGS_ONLY) return;
    try {
      const t = e.target;
      if (t && (/^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName) || t.isContentEditable)) return;
      if (_lb) return;
      /* A popover no longer swallows the paste: the URL box that used to catch
         it inside the source panel is gone, so Ctrl+V has to work there too. */
      if (!document.getElementById('as-root')) return;   // not on a gallery page
      const txt = ((e.clipboardData && e.clipboardData.getData('text')) || '').trim();
      if (!/^https?:\/\/\S+$/i.test(txt)) return;
      e.preventDefault();
      document.querySelectorAll('.as-pop').forEach(p => p.remove());
      asLog.info('Pasted a URL onto the gallery — importing ' + txt);
      sourceFromUrl(txt);
    } catch (err) { asLog.debug('paste handler: ' + (err && err.message)); }
  });
  document.addEventListener('keydown', e => {
    if (SETTINGS_ONLY) return;
    const t = e.target;
    // a popover (type picker / bulk pop) is open → Escape dismisses IT first
    // (wherever focus is), and other keys are swallowed so navigation/zoom/delete
    // don't act behind it. Mirrors the backdrop-click behaviour.
    if (document.querySelector('.as-pop')) {
      if (e.key === 'Escape') { e.preventDefault(); document.querySelectorAll('.as-pop').forEach(p => p.remove()); }
      else if (!(t && /^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName))) e.preventDefault();
      return;
    }
    if (t && /^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName)) return;
    if (_lb) {
      if (e.key === 'Escape') { e.preventDefault(); closeLightbox(); }
      else if (e.key === 'ArrowLeft') { e.preventDefault(); lbNav(-1); }
      else if (e.key === 'ArrowRight') { e.preventDefault(); lbNav(1); }
      else if (e.key === 'ArrowUp') { e.preventDefault(); zoomKey(1); }     // ↑ zoom in
      else if (e.key === 'ArrowDown') { e.preventDefault(); zoomKey(-1); }  // ↓ zoom out
      else if (e.key === 'p' || e.key === 'P') { e.preventDefault(); togglePlay(); }
      else if (e.key === 'Delete' || e.key === 'Backspace') { e.preventDefault(); deleteLbCover(); }
      else if (e.key === 'Enter') { e.preventDefault(); _lbEditCmt = true; paintCmtArea(document.getElementById('as-lb'), byId(_lb)); }   // start editing the comment
      else if (e.key === 'd' || e.key === 'D') { e.preventDefault(); const it = byId(_lb); if (it) dlOne(it); }   // download original
      return;
    }
    if (!root.isConnected || !root.querySelector('.as-card')) return;
    const map = { ArrowLeft: [-1, 0], ArrowRight: [1, 0], ArrowUp: [0, -1], ArrowDown: [0, 1] };
    if (map[e.key]) { e.preventDefault(); moveCursor(map[e.key][0], map[e.key][1]); }
    else if (e.key === 'Enter' && _cursorId) { e.preventDefault(); openLightbox(_cursorId); }
    else if (e.key === ' ' && _cursorId) { e.preventDefault(); const it = byId(_cursorId); if (it && !it._del) { it._sel = !it._sel; render(); } }
    else if ((e.key === 'Delete' || e.key === 'Backspace') && _cursorId) {   // mark the focused cover for removal (mirrors the viewer's Del)
      e.preventDefault();
      const it = byId(_cursorId); if (!it || it._del) return;
      if (it._rmOpen) { toast(`Its removal is open for votes already (edit #${it._rmOpen.edit})`); return; }   // #787
      const cards = [...root.querySelectorAll('.as-card:not(.del)')];
      const i = cards.findIndex(c => c.dataset.id === String(_cursorId));
      it._del = true; it._sel = false;
      // advance the cursor to the next remaining cover so Del can be pressed repeatedly
      const rest = cards.filter(c => c.dataset.id !== String(_cursorId));
      _cursorId = rest.length ? rest[Math.min(i, rest.length - 1)].dataset.id : null;
      render();
    }
  });

  function openBulkTypePop(btn) {
    document.querySelectorAll('.as-pop').forEach(p => p.remove());
    const sel = MODEL.filter(it => it._sel && !it._del); if (!sel.length) return;
    const pop = document.createElement('div'); pop.className = 'as-pop';
    pop.innerHTML = `<div class="as-pop-h">Set type on ${sel.length} ${ITEM}${sel.length===1?'':'s'}</div>`
      + `<div class="as-type-grid">${ALL_TYPES.map(t => `<label data-tip="Right-click: replace with only this type"><input type="checkbox" value="${esc(t)}"> ${esc(t)}</label>`).join('')}</div>`
      + `<div class="as-pop-f"><button class="as-btn as-pop-apply">Apply (replace)</button><button class="as-btn as-pop-add">Add</button></div>`;
    document.body.appendChild(pop);
    placePop(pop, btn.getBoundingClientRect());
    const picked = () => ALL_TYPES.filter(t => pop.querySelector(`input[value="${CSS.escape(t)}"]`).checked);
    const lbl = n => `${n} ${n === 1 ? ITEM : ITEMS}`;
    const replace = ts => { sel.forEach(it => it.types = ts.slice()); asLog.info(`Batch: set type [${ts.join(', ') || 'none'}] on ${lbl(sel.length)}`); if (SETTINGS.clearSelAfterOp) sel.forEach(it => it._sel = false); pop.remove(); render(); };   // #277
    pop.querySelector('.as-pop-apply').onclick = () => replace(picked());
    pop.querySelector('.as-pop-add').onclick = () => { const ts = picked(); sel.forEach(it => it.types = [...new Set([...it.types, ...ts])]); asLog.info(`Batch: added type [${ts.join(', ') || 'none'}] to ${lbl(sel.length)}`); if (SETTINGS.clearSelAfterOp) sel.forEach(it => it._sel = false); pop.remove(); render(); };   // #277
    // right-click a type → replace all selected with ONLY that type and close
    pop.querySelectorAll('.as-type-grid label').forEach(lab => lab.oncontextmenu = e => {
      e.preventDefault(); e.stopPropagation(); document.removeEventListener('mousedown', off); replace([lab.querySelector('input').value]);
    });
    const off = e => { if (!pop.contains(e.target)) { pop.remove(); document.removeEventListener('mousedown', off); } };
    setTimeout(() => document.addEventListener('mousedown', off), 0);
  }

  // #236: set one comment on every selected cover at once. Pre-fills the shared
  // comment if they already agree; Apply writes it, Clear blanks them all.
  // Reverse-image search one cover for a higher-res copy. Per-card (the 🔍 on each
  // tile) so it's unambiguously one image; a still-local NEW file has no public URL
  // to search by. Each engine opens pre-loaded with that URL — no download + drop.
  function openImageSearchPop(btn, it) {
    document.querySelectorAll('.as-pop').forEach(p => p.remove());
    const url = it && searchUrlFor(it);   // CAA original, or a sourced new cover's provider URL
    if (!url) { toast(it && it._new ? 'Reverse search needs a public image URL — this one is a local file (source it from a URL instead)' : 'Reverse search needs a published image'); return; }
    const pop = document.createElement('div'); pop.className = 'as-pop as-search-pop';
    // latest (main-branch) install link for the companion — never a feature branch
    const COMPANION_URL = 'https://raw.githubusercontent.com/majkinetor/musicbrainz-userscripts/main/userscripts/art_station/as_picker/as_picker.user.js';
    pop.innerHTML = `<div class="as-pop-h">Search for a higher-res copy<button class="as-search-all" type="button" data-tip="Open every engine in its own tab">Open all</button></div>`
      + IMG_SEARCH_ENGINES.map((e, i) => `<button class="as-btn as-search-eng" data-i="${i}">${esc(e.name)}</button>`).join('')
      + `<div class="as-search-foot">Requires the <a href="${COMPANION_URL}" target="_blank" rel="noopener">Art Station Picker</a> script for click-capture.</div>`;
    document.body.appendChild(pop);
    placePop(pop, btn.getBoundingClientRect());
    // mb_as_pick=<MBID> activates the picker companion (as_picker.user.js, if installed): it
    // lets you click the higher-res image anywhere and sends it back here. The value is THIS
    // release's MBID so the companion tags each pick with it — a pick stays destined for this
    // release even if this tab is closed, so it can't leak onto some other release's cover-art
    // page. Harmless if the companion isn't installed (engines ignore the unknown query param).
    // NB: a *query* param, not a #hash — Yandex's SPA blanks on an unexpected hash, not a param.
    const openEng = eng => {
      asLog.info(`Search: ${eng.name} ← ${it.types && it.types.length ? it.types.join('/') : ITEM} ${it.id}`);
      window.open(eng.u(url) + '&mb_as_pick=' + MBID, '_blank', 'noopener,noreferrer');
    };
    pop.querySelectorAll('.as-search-eng').forEach(b => b.onclick = () => { openEng(IMG_SEARCH_ENGINES[+b.dataset.i]); pop.remove(); });
    const allBtn = pop.querySelector('.as-search-all');
    if (allBtn) allBtn.onclick = () => { IMG_SEARCH_ENGINES.forEach(openEng); pop.remove(); };   // each in its own tab (the browser may ask to allow multiple popups the first time)
    const off = e => { if (!pop.contains(e.target) && e.target !== btn && !btn.contains(e.target)) { pop.remove(); document.removeEventListener('mousedown', off); } };
    setTimeout(() => document.addEventListener('mousedown', off), 0);
  }

  // #796 the release's title, artist and tracklist for the AI scan's prompt: one ws/2
  // read per page, on the first scan (the cover-art page shows no tracklist)
  let _aiRel = null;
  function aiRelease() {
    if (_aiRel) return _aiRel;
    const ri = releaseInfo();
    const base = { title: ri.title, artist: ri.artists.map(a => a.name).join(', '), url: ri.url, tracks: [] };
    _aiRel = (async () => {
      try {
        const r = await mbnFetch(`${location.origin}/ws/2/release/${MBID}?inc=recordings+artist-credits&fmt=json`, { headers: { Accept: 'application/json' } },
          { log: (l, m) => asLog[l === 'warn' ? 'warn' : 'info'](m) });
        if (!r || !r.ok) throw new Error(r ? 'HTTP ' + r.status : 'no answer');
        const j = await r.json();
        const media = j.media || [];
        const ac = (j['artist-credit'] || []).map(c => (c.name || (c.artist && c.artist.name) || '') + (c.joinphrase || '')).join('');
        return { ...base, title: j.title || base.title, artist: ac || base.artist,
          tracks: media.flatMap((m, mi) => (m.tracks || []).map(t => ({ pos: (media.length > 1 && /^\d+$/.test(t.number) ? (mi + 1) + '.' : '') + t.number, title: t.title }))) };
      } catch (e) { asLog.warn(`AI scan: no tracklist (${e.message})`); _aiRel = null; return base; }
    })();
    return _aiRel;
  }
  // the image as PNG (all a clipboard takes), at most 2400 px on its long side: enough
  // for small print, and within what the chats accept
  async function aiScanImage(it) {
    const src = (it._new ? it._file : (it._img || imgUrl(it.id))).replace(/^http:\/\//i, 'https://');
    const blob = (it._new && it._fileObj) ? it._fileObj
      : await fetch(src).then(r => r.ok ? r.blob() : Promise.reject(new Error('HTTP ' + r.status))).catch(() => gmFetch(src));
    const bmp = await createImageBitmap(blob);
    const k = Math.min(1, 2400 / Math.max(bmp.width, bmp.height));
    const c = document.createElement('canvas');
    c.width = Math.round(bmp.width * k); c.height = Math.round(bmp.height * k);
    c.getContext('2d').drawImage(bmp, 0, 0, c.width, c.height);
    try { bmp.close(); } catch (e) {}
    return new Promise((res, rej) => c.toBlob(b => b ? res(b) : rej(new Error('no PNG')), 'image/png'));
  }
  const _aiPrep = new Map();   // cover id -> Promise<{ png, prompt }>, started as the menu opens
  function aiScanPrep(it) {
    if (!_aiPrep.has(it.id)) _aiPrep.set(it.id, Promise.all([aiScanImage(it), aiRelease()])
      .then(([png, rel]) => ({ png, prompt: aiScanPrompt(it, rel) }))
      .catch(e => { _aiPrep.delete(it.id); throw e; }));
    return _aiPrep.get(it.id);
  }
  // Clipboard first, while this page has the focus, then the chat's tab (a click's
  // activation outlasts the short wait for the prepared image)
  async function aiScan(it, prov) {
    if (!it) return;
    let prep;
    try { prep = await aiScanPrep(it); }
    catch (e) { asLog.warn(`AI scan: image not read (${e.message})`); toast('AI scan: the image could not be read'); return; }
    const items = { 'image/png': prep.png };
    if (!prov.u) items['text/plain'] = new Blob([prep.prompt], { type: 'text/plain' });
    try { await navigator.clipboard.write([new ClipboardItem(items)]); }
    catch (e) { asLog.warn(`AI scan: clipboard refused (${e.message})`); toast('AI scan: the browser refused the clipboard'); return; }
    gmSave('aiScanLast', prov.name);
    asLog.info(`AI scan: ${prov.name} ← ${it.types && it.types.length ? it.types.join('/') : ITEM} ${it.id}`);
    window.open(prov.u ? prov.u(prep.prompt) : prov.home, '_blank', 'noopener,noreferrer');
    toast(prov.u ? 'Image copied: press Ctrl+V in the chat, then Enter' : 'Image and prompt copied: press Ctrl+V in the chat, then Enter', 6000);
  }
  function openAiScanPop(btn, it) {
    document.querySelectorAll('.as-pop').forEach(p => p.remove());
    if (!it) return;
    aiScanPrep(it).catch(() => {});   // the image and the tracklist load while a provider is picked
    const last = gmLoad('aiScanLast');
    const order = AI_PROVIDERS.slice().sort((a, b) => (b.name === last) - (a.name === last));
    const ico = p => `<img class="as-ai-ic" src="${esc(provIconUrl(p.dom))}" alt="" width="16" height="16">`;
    const pop = document.createElement('div'); pop.className = 'as-pop as-search-pop as-ai-pop';
    pop.innerHTML = `<div class="as-pop-h">Scan the credits with<button class="as-search-all as-ai-copy" type="button" data-tip="Copy only the prompt\nFor another AI, or to paste it by hand">Copy prompt</button></div>`
      + order.map(p => `<button class="as-btn as-search-eng${p.name === last ? ' as-ai-last' : ''}" data-n="${esc(p.name)}">${ico(p)}${esc(p.name)}</button>`).join('')
      + `<div class="as-search-foot">Paste the answer into the <a href="${AI_PARSER_DOC}" target="_blank" rel="noopener">Text parser</a>.</div>`;
    document.body.appendChild(pop);
    pop.querySelectorAll('.as-ai-ic').forEach(img => img.onerror = () => { img.style.visibility = 'hidden'; });   // a missing favicon (no inline handler: CSP)
    placePop(pop, btn.getBoundingClientRect());
    pop.querySelectorAll('.as-search-eng').forEach(b => b.onclick = () => { pop.remove(); aiScan(it, AI_PROVIDERS.find(p => p.name === b.dataset.n)); });
    pop.querySelector('.as-ai-copy').onclick = async () => {
      pop.remove();
      try { const prep = await aiScanPrep(it); await navigator.clipboard.writeText(prep.prompt); toast('Prompt copied'); }
      catch (e) { toast('AI scan: the prompt could not be copied'); }
    };
    const off = e => { if (!pop.contains(e.target) && e.target !== btn && !btn.contains(e.target)) { pop.remove(); document.removeEventListener('mousedown', off); } };
    setTimeout(() => document.addEventListener('mousedown', off), 0);
  }

  function openBulkCommentPop(btn) {
    document.querySelectorAll('.as-pop').forEach(p => p.remove());
    const sel = MODEL.filter(it => it._sel && !it._del); if (!sel.length) return;
    const common = sel.every(it => it.comment === sel[0].comment) ? sel[0].comment : '';
    const pop = document.createElement('div'); pop.className = 'as-pop as-cmt-pop';
    pop.innerHTML = `<div class="as-pop-h">Comment on ${sel.length} ${ITEM}${sel.length===1?'':'s'}</div>`
      + `<input class="as-bulk-cmt" placeholder="comment…" spellcheck="false" list="as-cmt-presets" value="${esc(common)}">`
      + `<div class="as-pop-f"><button class="as-btn as-pop-apply">Apply</button><button class="as-btn as-bulk-cmt-clr">Clear</button></div>`;
    document.body.appendChild(pop);
    placePop(pop, btn.getBoundingClientRect());
    const inp = pop.querySelector('.as-bulk-cmt'); inp.focus(); inp.select();
    const apply = v => { sel.forEach(it => it.comment = v); asLog.info(`Batch: ${v ? `set comment “${v}”` : 'cleared comment'} on ${sel.length} ${sel.length === 1 ? ITEM : ITEMS}`); if (SETTINGS.clearSelAfterOp) sel.forEach(it => it._sel = false); pop.remove(); render(); };   // #277
    pop.querySelector('.as-pop-apply').onclick = () => apply(inp.value);
    pop.querySelector('.as-bulk-cmt-clr').onclick = () => apply('');
    inp.onkeydown = e => { if (e.key === 'Enter') { e.preventDefault(); apply(inp.value); } else if (e.key === 'Escape') { e.preventDefault(); pop.remove(); } };
    const off = e => { if (!pop.contains(e.target) && e.target !== btn) { pop.remove(); document.removeEventListener('mousedown', off); } };
    setTimeout(() => document.addEventListener('mousedown', off), 0);
  }

  // ── #239 postable report (Markdown / HTML) of the selected covers ─────────────
  // release artist(s) + title, linked, parsed from the page header
  function releaseInfo() {
    const title = (document.querySelector('h1 bdi') || document.querySelector('h1'))?.textContent?.trim() || 'release';
    const sub = document.querySelector('p.subheader') || document.querySelector('.subheader');
    const artists = sub ? [...sub.querySelectorAll('a[href*="/artist/"]')]
      .filter(a => !/\/create(\?|$)/.test(a.getAttribute('href')))
      .map(a => ({ name: a.textContent.trim(), url: location.origin + a.getAttribute('href').split(/[?#]/)[0] })) : [];
    return { title, url: `${location.origin}${ENT.base}`, artists };   // #623 X2: this server, not always production
  }
  const pad2 = n => String(n).padStart(2, '0');
  // the logged-in MB user, for the export manifest ("Exported by"). Read the name from
